INSERT INTO sample_tracker.app_role (id, name, is_active)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM sample_tracker.app_role), 'SUPERVISEUR_REGION', true
WHERE NOT EXISTS (SELECT 1 FROM sample_tracker.app_role WHERE name = 'SUPERVISEUR_REGION');

INSERT INTO sample_tracker.app_role (id, name, is_active)
SELECT (SELECT COALESCE(MAX(id), 0) + 1 FROM sample_tracker.app_role), 'SUPERVISEUR_DISTRICT', true
WHERE NOT EXISTS (SELECT 1 FROM sample_tracker.app_role WHERE name = 'SUPERVISEUR_DISTRICT');

SELECT setval(
	pg_get_serial_sequence('sample_tracker.app_role', 'id'),
	(SELECT MAX(id) FROM sample_tracker.app_role)
);
